static bool queue_over_write(espnow_msg_id_t msg_id, const void *const data, size_t data_len, void *arg, TickType_t xTicksToWait) /* <=== queue_over_write */ 
{
    if (msg_id == ESPNOW_EVENT_RECV_ACK) {
        if (!g_ack_queue) {
            return false;
        }
        return xQueueSend(g_ack_queue, &data, xTicksToWait);
    } else {
        if (!g_espnow_queue) {
            return false;
        }

        espnow_event_ctx_t espnow_event = {
            .msg_id = msg_id,
            .data_len = data_len,
            .data = (void *)data,
            .handle = arg
        };

        return xQueueSend(g_espnow_queue, &espnow_event, xTicksToWait);
    }
}

